<script setup lang="ts">
import {computed,nextTick,onBeforeUnmount,onMounted,ref,watch} from 'vue'
import {ArrowUpRight,Minus,Plus,Send,X,Sparkles} from 'lucide-vue-next'
import MesRobot from './MesRobot.vue'
import QueryTable from './QueryTable.vue'
import request from '@/utils/request'
import {useAuthStore} from '@/stores/auth'
import {agentMessages as messages,agentSession as session,agentPreviousSkill as previous,agentOwner} from '@/stores/agentChat'
type Row=Record<string,any>
const auth=useAuthStore(),open=ref(false),busy=ref(false),question=ref(''),error=ref(''),catalog=ref<Row>({skills:[],model:{}}),selected=ref('')
const launcher=ref<HTMLButtonElement>(),input=ref<HTMLTextAreaElement>(),feed=ref<HTMLElement>()
const position=ref({x:24,y:18}),dragging=ref(false)
let drag:{x:number;y:number;right:number;bottom:number}|undefined,moved=false
const names:Row={PENDING:'等待确认',SUCCEEDED:'已完成',CLARIFICATION:'待补充',CANCELLED:'已取消',FAILED:'失败',STALE:'需重新核对',EXPIRED:'已过期'}
const style=computed(()=>({right:position.value.x+'px',bottom:position.value.y+'px'}))
const panelStyle=computed(()=>({right:Math.min(position.value.x,Math.max(12,window.innerWidth-432))+'px',bottom:Math.min(position.value.y+135,Math.max(12,window.innerHeight-620))+'px'}))
watch(()=>auth.currentUser?.id,id=>{if(agentOwner.value!==id){messages.value=[];session.value='';previous.value='';agentOwner.value=id;catalog.value={skills:[],model:{}};open.value=false}},{immediate:true})
function clamp(){position.value={x:Math.min(Math.max(8,position.value.x),Math.max(8,innerWidth-120)),y:Math.min(Math.max(8,position.value.y),Math.max(8,innerHeight-150))}}
function down(e:PointerEvent){if(e.button!==0)return;moved=false;drag={x:e.clientX,y:e.clientY,right:position.value.x,bottom:position.value.y};launcher.value?.setPointerCapture(e.pointerId)}
function move(e:PointerEvent){if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.hypot(dx,dy)>5){moved=true;dragging.value=true}if(moved){position.value={x:drag.right-dx,y:drag.bottom-dy};clamp()}}
function up(){if(!drag)return;drag=undefined;dragging.value=false;if(moved){try{localStorage.setItem('mes-robot-position',JSON.stringify(position.value))}catch{/* Storage may be unavailable. */}}}
async function toggle(){if(moved){moved=false;return}open.value=!open.value;if(open.value){await nextTick();input.value?.focus();if(!catalog.value.skills.length)try{catalog.value=await request.get('/agent/skills')}catch(e:any){error.value=e.message}}}
function close(){open.value=false;nextTick(()=>launcher.value?.focus())}
async function scroll(){await nextTick();if(feed.value)feed.value.scrollTop=feed.value.scrollHeight}
async function send(){if(busy.value||!question.value.trim())return;busy.value=true;error.value='';try{const owner=auth.currentUser?.id;const run=await request.post<Row>('/agent/messages',{question:question.value.trim(),skillId:selected.value,previousSkill:previous.value,...(session.value?{sessionId:session.value}:{})},{timeout:35000});if(owner!==auth.currentUser?.id)return;messages.value.push(run);if(run.reply.sessionId){session.value=run.reply.sessionId;previous.value=run.skill_id}question.value='';await scroll()}catch(e:any){error.value=e.message}finally{busy.value=false;nextTick(()=>input.value?.focus())}}
async function action(url:string){if(busy.value)return;busy.value=true;error.value='';const owner=auth.currentUser?.id;try{const run=await request.post<Row>(url);if(owner!==auth.currentUser?.id)return;const index=messages.value.findIndex(item=>item.id===run.id);if(index<0)messages.value.push(run);else messages.value[index]=run;await scroll()}catch(e:any){if(owner===auth.currentUser?.id)error.value=e.message}finally{busy.value=false}}
function fresh(){messages.value=[];session.value='';previous.value='';question.value='';error.value='';selected.value='';input.value?.focus()}
function choose(s:Row){selected.value=s.id;question.value=s.example;input.value?.focus()}
function escape(e:KeyboardEvent){if(e.key==='Escape'&&open.value)close()}
onMounted(()=>{try{const saved=JSON.parse(localStorage.getItem('mes-robot-position')||'null');if(Number.isFinite(saved?.x)&&Number.isFinite(saved?.y))position.value=saved}catch{/* Use default corner. */}clamp();window.addEventListener('resize',clamp);window.addEventListener('keydown',escape)})
onBeforeUnmount(()=>{window.removeEventListener('resize',clamp);window.removeEventListener('keydown',escape)})
</script>
<template><Teleport to="body">
 <div class="robot-dock" :style="style" :class="{dragging}"><span v-if="!open" class="robot-hello">有任务，找小栗 <Sparkles :size="11"/></span><button ref="launcher" class="robot-launcher" aria-label="打开小栗业务智能体" :aria-expanded="open" aria-controls="mes-robot-panel" @pointerdown="down" @pointermove="move" @pointerup="up" @pointercancel="up" @click="toggle"><MesRobot :thinking="busy"/><span class="robot-name"><i></i>小栗 · MES</span></button></div>
 <Transition name="robot-panel"><section v-if="open" id="mes-robot-panel" class="robot-chat" :style="panelStyle" role="region" aria-label="小栗业务智能体对话">
  <header class="robot-chat-head"><div class="robot-avatar"><MesRobot :thinking="busy"/></div><div><h2>小栗 <span>制造协作助手</span></h2><p><i></i>{{catalog.model.mode==='remote'?(catalog.model.configured?'大模型技能模式':'等待大模型配置'):'本地技能模式'}} · 为你连接业务数据</p></div><div class="robot-head-actions"><button :disabled="busy" aria-label="开始新会话" title="新会话" @click="fresh"><Plus :size="17"/></button><button aria-label="收起机器人对话" @click="close"><Minus :size="18"/></button></div></header>
  <div ref="feed" class="robot-chat-feed" aria-live="polite" :aria-busy="busy">
   <div v-if="!messages.length" class="robot-intro"><div class="robot-intro-art"><MesRobot/></div><h3>你好，我是小栗。</h3><p>查库存、看缺料、追工单，<br/>把生产现场的事，交给我一起处理。</p><div class="robot-quick"><button v-for="s in catalog.skills" :key="s.id" @click="choose(s)">{{s.name}}<ArrowUpRight :size="12"/></button></div><p v-if="!catalog.skills.length" class="robot-hint">正在读取技能；当前岗位没有可用技能时，请联系管理员。</p></div>
   <article v-for="run in messages" :key="run.id" class="robot-turn"><p class="robot-user-message">{{run.question}}</p><div class="robot-reply"><div class="robot-reply-label">小栗 <span>{{names[run.status]||run.status}}</span></div><p>{{run.reply.summary}}</p><p v-for="c in run.reply.query?.clarifications||[]" :key="c" class="robot-clarification">{{c}}</p><div v-if="run.reply.data" class="robot-mini-data"><p class="robot-source">{{run.reply.data.evidence}}</p><template v-if="run.skill_id==='maintenance'"><div v-for="r in run.reply.data.rows?.slice(0,5)" :key="r.id" class="robot-maintenance-row"><strong>{{r.equipment_name}}</strong><span>{{r.name}} · {{r.due_date}}</span></div></template><QueryTable v-else :rows="(run.reply.data.rows||[]).slice(0,5)"><template #default="{row}"><button v-if="run.reply.canPropose&&row.status!=='CONFIRMED'" :disabled="busy" class="robot-detail-link" @click="action('/agent/proposals/'+row.material_id)">生成确认任务</button></template></QueryTable><small>预览前 5 条 · 查询时间 {{run.reply.data.updatedAt}}</small></div><div v-if="run.reply.preview" class="robot-confirm"><strong>补货建议核对</strong><p>{{run.reply.preview.material_name}} · {{run.reply.preview.material_code}}</p><p>当前库存：{{run.reply.preview.current_quantity}} {{run.reply.preview.unit}}<br/>安全库存：{{run.reply.preview.safety_stock}} {{run.reply.preview.unit}}<br/>建议补货：{{run.reply.preview.suggested_quantity}} {{run.reply.preview.unit}}</p><div v-if="run.status==='PENDING'" class="robot-confirm-actions"><button :disabled="busy" @click="action('/agent/runs/'+run.id+'/confirm')">确认登记建议</button><button :disabled="busy" @click="action('/agent/runs/'+run.id+'/cancel')">取消</button></div></div><router-link :to="{path:'/assistant',query:{run:run.id}}" class="robot-detail-link" @click="close">{{run.skill_id==='replenishment'?'查看建议并核对操作':'查看完整任务与来源'}}<ArrowUpRight :size="13"/></router-link></div></article>
   <div v-if="busy" class="robot-typing"><span></span><span></span><span></span><small>小栗正在处理任务…</small></div>
  </div>
  <div v-if="error" class="robot-chat-error" role="alert">{{error}}<button aria-label="关闭错误提示" @click="error=''"><X :size="13"/></button></div>
  <form class="robot-chat-compose" @submit.prevent="send"><div class="robot-skill-select"><label for="robot-skill">当前技能</label><select id="robot-skill" v-model="selected" :disabled="busy"><option value="">自动识别任务</option><option v-for="s in catalog.skills" :key="s.id" :value="s.id">{{s.name}}</option></select></div><label for="robot-question" class="sr-only">给小栗的任务</label><textarea id="robot-question" ref="input" v-model="question" rows="2" maxlength="1200" :disabled="busy" placeholder="告诉小栗，你想完成什么…" @keydown.ctrl.enter.prevent="send"></textarea><div class="robot-compose-bottom"><span>{{question.length}}/1200 · Ctrl+Enter</span><button :disabled="busy||!question.trim()" type="submit" aria-label="发送给小栗"><Send :size="15"/>发送</button></div></form>
  <footer class="robot-chat-footer"><span>业务写入需核对确认</span><router-link to="/assistant" @click="close">完整工作台 <ArrowUpRight :size="12"/></router-link></footer>
 </section></Transition>
</Teleport></template>
<style scoped>
.robot-confirm{margin-top:12px;padding:12px;border:1px solid #e3dcd2;border-radius:10px;background:#f9f7f5}.robot-confirm-actions{display:flex;gap:12px;margin-top:8px}.robot-confirm-actions button{padding:5px 9px;border:1px solid #beaf9a;border-radius:7px}.robot-confirm-actions button:disabled{opacity:.5}

.robot-dock{position:fixed;z-index:60;width:112px;user-select:none}.robot-launcher{position:relative;display:block;width:112px;height:144px;border:0;background:none;cursor:grab;padding:0;touch-action:none;outline-offset:5px;border-radius:35px}.robot-launcher:focus-visible{outline:3px solid #ab9272}.dragging .robot-launcher{cursor:grabbing}.dragging :deep(.robot-float){animation-play-state:paused}.robot-launcher :deep(.mes-robot){height:125px;transition:transform .2s}.robot-launcher:hover :deep(.mes-robot){transform:scale(1.06)}
.robot-name{display:flex;align-items:center;justify-content:center;gap:5px;background:#fbfaf9ea;border:1px solid #e3dcd2;border-radius:20px;padding:5px 8px;color:#867763;font:10px 'Microsoft YaHei',sans-serif;box-shadow:0 4px 13px #8e7f6b18;white-space:nowrap}.robot-name i,.robot-chat-head p i{display:inline-block;width:5px;height:5px;background:#9f8c72;border-radius:50%}.robot-hello{position:absolute;right:8px;bottom:151px;display:flex;align-items:center;gap:5px;padding:8px 11px;background:#fffefa;border:1px solid #e8e3dd;border-radius:12px 12px 2px 12px;font-size:11px;color:#857a6b;white-space:nowrap;box-shadow:0 5px 20px #94836c15;pointer-events:none}
.robot-chat{position:fixed;z-index:61;width:420px;max-height:min(680px,calc(100dvh - 24px));display:flex;flex-direction:column;border:1px solid #dfd7cc;border-radius:22px;background:#fdfcfbf7;box-shadow:0 18px 80px #62533f30,0 3px 12px #81705912;backdrop-filter:blur(24px);overflow:hidden;font-family:'Segoe UI','Microsoft YaHei',sans-serif;color:#695d4e;color-scheme:light}.robot-chat-head{display:flex;align-items:center;gap:10px;padding:12px 16px;background:linear-gradient(115deg,#f9f6f3,#f3f0eb);border-bottom:1px solid #e7e0d7;flex-shrink:0}.robot-avatar{width:48px;height:58px;flex-shrink:0}.robot-chat-head h2{font-size:17px;font-weight:650;color:#695b48;margin:0}.robot-chat-head h2 span{font-size:10px;font-weight:400;color:#958b7d;margin-left:6px}.robot-chat-head p{font-size:9px;color:#9e9589;margin-top:6px;display:flex;align-items:center;gap:5px}.robot-head-actions{display:flex;gap:3px;margin-left:auto}.robot-head-actions button{border:0;background:transparent;border-radius:8px;padding:7px;color:#968b7d}.robot-head-actions button:hover{background:#eae4db}
.robot-chat-feed{overflow-y:auto;overscroll-behavior:contain;min-height:130px;max-height:365px;flex:1;padding:18px;scrollbar-width:thin;scrollbar-color:#dbd3c8 transparent}.robot-intro{text-align:center;padding:0 6px 12px}.robot-intro-art{width:100px;height:112px;margin:auto}.robot-intro h3{font-size:20px;font-weight:600;color:#7f6d56;margin:8px 0}.robot-intro>p{font-size:12px;line-height:1.9;color:#9d9488;margin:10px 0 16px}.robot-quick{display:grid;grid-template-columns:1fr 1fr;gap:8px}.robot-quick button{padding:10px;border:1px solid #e3dcd2;border-radius:10px;background:#f9f7f5;color:#91816d;font-size:11px;text-align:left;display:flex;align-items:center;justify-content:space-between}.robot-quick button:hover{border-color:#beaf9a;background:#f5f1ec}
.robot-user-message{margin:0 0 12px auto;max-width:90%;padding:10px 14px;border-radius:13px 13px 3px 13px;background:linear-gradient(115deg,#f1ece5,#f4f0eb);color:#7a6a55;font-size:12px;line-height:1.8;white-space:pre-wrap;overflow-wrap:anywhere;width:fit-content}.robot-reply{font-size:12px;line-height:1.9;padding:13px;background:#fff;border:1px solid #ebe7e2;border-radius:3px 14px 14px 14px;min-width:0}.robot-reply-label{display:flex;gap:8px;color:#88765e;font-size:11px;margin-bottom:8px;font-weight:600}.robot-reply-label span{font-weight:400;font-size:9px;color:#70a38f;background:#eff8f3;padding:0 6px;border-radius:4px}.robot-turn{margin-bottom:18px}.robot-mini-data{margin-top:12px;max-width:100%;overflow:hidden}.robot-source{color:#9d9489;font-size:10px;line-height:1.7;margin-bottom:9px}.robot-mini-data :deep(table){font-size:10px}.robot-mini-data :deep(th),.robot-mini-data :deep(td){padding:6px 8px}.robot-mini-data small{font-size:9px;color:#a0988e;display:block;margin-top:8px}.robot-maintenance-row{border-bottom:1px solid #efece8;padding:6px 0}.robot-maintenance-row strong{font-size:11px}.robot-maintenance-row span{display:block;font-size:10px;color:#9d9489}.robot-detail-link{display:flex;align-items:center;gap:5px;margin-top:12px;font-size:11px;color:#99805f}.robot-clarification{color:#9d7b3e}.robot-typing{display:flex;align-items:center;gap:4px;color:#9c9286;padding:10px}.robot-typing>span{width:5px;height:5px;border-radius:50%;background:#bcab94;animation:robot-dot 1s infinite alternate}.robot-typing>span:nth-child(2){animation-delay:.2s}.robot-typing>span:nth-child(3){animation-delay:.4s}.robot-typing small{font-size:10px;margin-left:7px}
.robot-chat-compose{border-top:1px solid #eae5de;background:#f9f7f5dd;padding:12px 16px;flex-shrink:0}.robot-skill-select{display:flex;align-items:center;gap:8px;margin-bottom:8px;font-size:10px;color:#a1998e}.robot-skill-select select{max-width:180px;color:#867764;background:#fff;border:1px solid #e3dbd1;border-radius:7px;font-size:10px;padding:4px 6px;outline:none}.robot-chat-compose textarea{box-sizing:border-box;width:100%;resize:none;border:1px solid #e4ddd3;border-radius:10px;padding:10px 12px;min-height:63px;font-size:12px;line-height:1.6;background:#fff;color:#6b5e4e;outline:none}.robot-chat-compose textarea:focus{border-color:#c0ae96;box-shadow:0 0 0 3px #bba68a12}.robot-chat-compose textarea::placeholder{color:#afa79d}.robot-compose-bottom{display:flex;justify-content:space-between;align-items:center;margin-top:8px}.robot-compose-bottom>span{font-size:9px;color:#aaa297}.robot-compose-bottom button{display:flex;align-items:center;gap:6px;background:linear-gradient(110deg,#af997b,#bba68b);border:1px solid #c9b9a4;border-radius:9px;padding:7px 12px;font-size:11px;color:#fff}.robot-compose-bottom button:disabled{opacity:.5;cursor:not-allowed}.robot-chat-footer{display:flex;justify-content:space-between;padding:9px 16px;font-size:9px;color:#aea79e;border-top:1px solid #f0ede8;flex-shrink:0}.robot-chat-footer a{display:flex;align-items:center;gap:3px;color:#978b7a}.robot-chat-error{background:#fff0f1;color:#ae6070;padding:9px 14px;font-size:11px;display:flex;align-items:center;justify-content:space-between;gap:5px;flex-shrink:0}.robot-chat-error button{padding:3px}
.robot-panel-enter-active,.robot-panel-leave-active{transition:opacity .18s,transform .18s}.robot-panel-enter-from,.robot-panel-leave-to{opacity:0;transform:translateY(14px) scale(.98)}@keyframes robot-dot{to{opacity:.25;transform:translateY(-3px)}}
@media(max-width:760px){.robot-dock{width:90px}.robot-launcher{width:90px;height:118px}.robot-launcher :deep(.mes-robot){height:99px}.robot-name{font-size:9px;padding:4px}.robot-hello{bottom:124px;font-size:9px;padding:6px 8px}.robot-chat{right:10px!important;bottom:12px!important;width:calc(100vw - 20px);max-height:calc(100dvh - 24px);border-radius:18px}.robot-chat-feed{max-height:calc(100dvh - 295px)}.robot-chat-head{padding:8px 12px}.robot-intro-art{height:90px;width:80px}.robot-intro h3{font-size:18px}}
@media(prefers-reduced-motion:reduce){.robot-typing>span{animation:none}.robot-panel-enter-active,.robot-panel-leave-active{transition:none}}

</style>
